/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { BombCalorimeterScreen } from "../../src/bomb/BombCalorimeterScreen.js";
import CalorimetryLabColors from "../../src/CalorimetryLabColors.js";
import { CoffeeCupScreen } from "../../src/coffee-cup/CoffeeCupScreen.js";
import { HessLawScreen } from "../../src/hess-law/HessLawScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { CalorimetryLabPreferencesModel } from "../../src/preferences/CalorimetryLabPreferencesModel.js";
import { SpecificHeatScreen } from "../../src/specific-heat/SpecificHeatScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from calorimetryLabQueryParameters.
  const simPreferences = new CalorimetryLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new SpecificHeatScreen({
      name: stringManager.getScreenNames().specificHeatStringProperty,
      tandem: Tandem.ROOT.createTandem("specificHeatScreen"),
      showCalculationsProperty: simPreferences.showCalculationsProperty,
      backgroundColorProperty: CalorimetryLabColors.backgroundColorProperty,
    }),
    new CoffeeCupScreen({
      name: stringManager.getScreenNames().coffeeCupStringProperty,
      tandem: Tandem.ROOT.createTandem("coffeeCupScreen"),
      showCalculationsProperty: simPreferences.showCalculationsProperty,
      backgroundColorProperty: CalorimetryLabColors.backgroundColorProperty,
    }),
    new BombCalorimeterScreen({
      name: stringManager.getScreenNames().bombStringProperty,
      tandem: Tandem.ROOT.createTandem("bombScreen"),
      showCalculationsProperty: simPreferences.showCalculationsProperty,
      backgroundColorProperty: CalorimetryLabColors.backgroundColorProperty,
    }),
    new HessLawScreen({
      name: stringManager.getScreenNames().hessLawStringProperty,
      tandem: Tandem.ROOT.createTandem("hessLawScreen"),
      showCalculationsProperty: simPreferences.showCalculationsProperty,
      backgroundColorProperty: CalorimetryLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { CalorimetryLabColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
